      "old": "#define NSEC_PER_USEC 1000ULL\n#define NSEC_PER_MSEC 1000000ULL",
      "new": "#define NSEC_PER_USEC 1000ULL\n#define NSEC_PER_MSEC 1000000ULL\n#define NSEC_PER_SEC 1000000000ULL"
